class Query(graphene.ObjectType):
    performance_review = graphene.Field(PerformanceReviewType, review_id=graphene.Int(required=True))

    def resolve_performance_review(self, info, review_id):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Authentication required.")
        try:
            return PerformanceReview.objects.filter(
                Q(employee=user) | Q(reviewer=user) | Q(hr_partner=user),
                id=review_id
            ).get()
        except PerformanceReview.DoesNotExist:
            raise GraphQLError("Review not found or access denied.")
